package controller;
import java.io.IOException;import java.sql.Connection;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import dao.InventoryDao;import models.Employee;import util.DatabaseConnection;
@WebServlet("/account") public class AccountController extends HttpServlet{private final InventoryDao dao=new InventoryDao();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/views/account.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{Employee e=(Employee)r.getSession().getAttribute("currentUser");String old=r.getParameter("currentPassword"),next=r.getParameter("newPassword"),confirm=r.getParameter("confirmPassword"),m;if(!e.password.equals(old))m="Current password is incorrect.";else if(next==null||next.length()<8)m="New password must contain at least 8 characters.";else if(!next.equals(confirm))m="New passwords do not match.";else{try(Connection c=DatabaseConnection.getConnection()){dao.password(c,e.id,next);e.password=next;m="Password changed successfully.";}catch(Exception x){m="Password could not be changed.";}}r.setAttribute("message",m);r.getRequestDispatcher("/views/account.jsp").forward(r,s);}}
